namespace IdentityServer.Modules.Accounts
{
    /// <summary>
    /// Records security-relevant events generated by the IdentityServer host.
    /// </summary>
    public interface IIdentitySecurityEventRecorder
    {
        /// <summary>
        /// Persists a security event without allowing recording failures to interrupt authentication flows.
        /// </summary>
        /// <param name="action">The security action that occurred.</param>
        /// <param name="userId">The related identity user, when available.</param>
        /// <param name="clientId">The related OpenID client, when available.</param>
        /// <param name="detailsJson">Optional structured event details.</param>
        /// <param name="cancellationToken">The cancellation token for the persistence operation.</param>
        Task Record(string action, Guid? userId = null, string? clientId = null, string? detailsJson = null, CancellationToken cancellationToken = default);
    }
}
